export function finishMail(this: Store, quest: MailQuest) {
  if (quest.item && quest.to) {
    const mem = this.data.mail.memory ?? {};
    const items = mem[quest.to] ?? [];
    // Keep only the newest 3 items
    this.data.mail.memory = {
      ...mem,
      [quest.to]: [quest.item, ...items].slice(0, 3),
    };
  }
  this.data.mail.quest = null;
  this.data.mail.delivered += 1;
  this.data.quests.active = null;
  this.commit();
}
EOF
